insert into public.communities(slug,name,description,guidelines) values
('moving-forward','Breakup & Moving Forward','A little space for letting go and growing.','No contact-detail sharing or pressure to reconnect. Ask before giving advice.'),
('relationships','Love & Relationship Struggles','The messy, meaningful parts of caring about someone.','Respect boundaries. No sexual solicitation or identifying others.'),
('finding-connection','Loneliness & Finding Connection','A familiar feeling and a friendly hello.','Connection is always mutual. Never pressure someone to reply.'),
('emotional-wellbeing','Depression & Emotional Wellbeing','For feelings that are hard to put into words.','Share experiences, not diagnoses. No harmful instructions. Use content warnings.'),
('financial-stress','Financial Stress','Money worries without judgement.','No lending, fundraising, investing tips, sales, or requests for financial details.'),
('study-pressure','Study & Exam Pressure','Share the weight of expectations.','No pressure to disclose your school, marks, or exact location.'),
('founder-pressure','Founders & Startup Pressure','Behind the building is a person.','No pitching, lead generation, recruiting, or unsolicited promotions.'),
('career-challenges','Jobs & Career Challenges','Crossroads and your next chapter.','Protect employer and colleague identities. No job scams or recruiting fees.'),
('family-personal','Family & Personal Struggles','Boundaries and everything close to home.','Protect family members’ identities. Respect different lived experiences.'),
('everything-at-once','Everything at Once','When several challenges happen together.','No comparing or ranking distress. Start with whatever feels comfortable.');
